-- 20260909_03_hapus_duplikat_pariwisata.sql
-- Bersihkan 248 barang DUPLIKAT hasil paste-3x saat penyusunan awal
-- Dinas Pariwisata dan Kebudayaan (skpd_id 23, golongan 1.3.2).
--
-- LATAR (laporan user 2026-09-09): berkas import ter-paste TIGA KALI, jadi
-- 124 barang tercatat 372 kali. Daftar 248 NIBAR yang harus dibuang sudah
-- dipisahkan user di "Duplicate Dinas Pariwisata.xlsx"; yang 124 sisanya
-- (NIBAR di luar daftar ini) DIPERTAHANKAN apa adanya.
-- Σ nilai perolehan yang dibuang: Rp91.492.800.
--
-- DIVERIFIKASI KE PRODUKSI 2026-09-09 sebelum dijalankan (bukan diasumsikan) —
-- `aset.created_at` memisahkan kedua batch 1.3.2 Dinas Pariwisata dgn bersih:
--   2026-07-16 14:56 → 532 barang, Rp3.810.462.836, DIBUANG 0  (batch lama,
--                      tak tersentuh daftar ini sama sekali)
--   2026-09-04 06:29 → 372 barang, Rp137.239.200, dibuang 248, sisa 124
-- Ketiga paste jatuh di MENIT yang sama, jadi ia satu gerombolan, bukan tiga.
-- Aritmetikanya menutup dua arah: 124 x 3 = 372 dan Rp45.746.400 x 3 =
-- Rp137.239.200, sementara yang dibuang tepat 2 salinan (Rp45.746.400 x 2 =
-- Rp91.492.800). Jadi daftar user membuang PERSIS dua salinan — tak kurang,
-- tak lebih. Selain itu: 248/248 NIBAR ketemu di `aset` DAN di `aset_awal_2026`,
-- 248 baris ledger (tepat satu `saldo_awal` per aset), 0 yang sudah bergerak,
-- 0 yang bukan skpd 23 / golongan 1.3.2.
--
-- ⚠️ KENAPA BUKAN "DELETE FROM transaksi_bmd":
--   Baris ledger `saldo_awal` ketiga salinan itu SUDAH ADA, dan `transaksi_bmd`
--   append-only MUTLAK (trigger `trg_transaksi_bmd_immutable` menolak
--   DELETE/UPDATE untuk SEMUA role). Escape hatch DELETE pernah dicoba
--   (migrasi 17/18) dan terbukti berbahaya sampai harus direvert
--   (20260704_19): begitu baris ledger ikut terhapus, replay visibilitas
--   kehilangan jejaknya dan barang yang sudah "dihapus" MUNCUL LAGI di Daftar
--   Barang & Penyusutan. Resep ROLLBACK di 20260904_02/20260905_05 sudah
--   menuliskan jalan yang benar untuk keadaan ini, dan itu yang dipakai:
--     duplikat diperlakukan seperti SALAH CATAT biasa —
--     `koreksi_pencatatan_ganda` DI-BACKDATE ke tanggal perolehannya.
--   Jenis itu ada di whitelist `fn_cek_tahun_buku` (20260708_04) sehingga boleh
--   bertanggal di tahun terkunci, dan ada di daftar SEMBUNYI
--   (lib/visibilitas.ts + `v_hide` di `fn_dbar_hidden`) sehingga barangnya
--   hilang dari SEMUA periode — bukan cuma sejak sekarang.
--   Pola persis 20260819_01 (duplikat Import Gedung), yang sudah terbukti.
--
-- HASIL YANG DIHARAPKAN — sama persis dengan "dihapus dari database":
--   · Daftar Barang, Penyusutan, KIBAR ....... 248 barang itu tak muncul lagi
--   · Laporan BMD & Rekonsiliasi (semua periode) ... nilainya tak terhitung
--   · Saldo Awal → Daftar Barang Awal ........ barisnya BENAR-BENAR dihapus
--     (`aset_awal_2026` tabel snapshot display-only, bukan ledger — DELETE sah
--      di sini; precedent 20260812_07, 20260819_01, 20260819_02)
--   Yang tersisa cuma jejak audit di ledger, yang memang harus tersisa.
--
-- Baris `koreksi_pencatatan_ganda` ini `created_by IS NULL` → di menu
-- Pelaporan → Koreksi ia TIDAK tampil (penyaring "Asal baris" berbawaan
-- `menu`, aturan 2026-09-07), dan `nilai`-nya 0 sehingga tak menggeser satu
-- rupiah pun di laporan mana pun.
--
-- IDEMPOTEN: aman dijalankan ulang (semua langkah ber-NOT EXISTS / ber-guard).
-- TIDAK ADA perubahan kode aplikasi yang menyertai — murni perbaikan data.
-- ⚠️ SESUDAH INI: JALANKAN ENGINE untuk 2026-S1 lalu 2026-S2.
-- ============================================================================

-- ── 1. Daftar NIBAR yang dibuang (dari berkas user) ─────────────────────────
-- Tabel staging DIPERTAHANKAN sesudah migrasi: ia yang membuat langkah
-- verifikasi & rollback di bawah bisa ditulis tanpa mengetik ulang 248 nomor.
DROP TABLE IF EXISTS stg_dup_pariwisata;
CREATE TABLE stg_dup_pariwisata (nibar text PRIMARY KEY);


-- ── 2. GUARD — batal TOTAL kalau ada satu saja yang tak sesuai dugaan ───────
-- Seluruh migrasi ini satu transaksi, jadi RAISE di sini me-ROLLBACK semuanya.
-- Ini yang membedakan "membuang 248 salinan" dari "membuang barang sungguhan".
DO $$
DECLARE
  n_stg int; n_aset int; n_luar int; n_gerak int; n_tglnull int; n_sisa int; v_nilai numeric;
BEGIN
  SELECT count(*) INTO n_stg FROM stg_dup_pariwisata;
  IF n_stg <> 248 THEN
    RAISE EXCEPTION 'Daftar NIBAR tidak utuh: % baris (harus 248).', n_stg;
  END IF;

  -- (a) semuanya harus KETEMU di register. Kurang = berkasnya bukan yang ini,
  --     atau sebagian sudah terlanjur dibuang dengan cara lain.
  SELECT count(*) INTO n_aset
    FROM aset a JOIN stg_dup_pariwisata s ON s.nibar = a.nibar;
  IF n_aset <> 248 THEN
    RAISE EXCEPTION 'Hanya % dari 248 NIBAR yang ketemu di tabel aset — periksa dulu, jangan diteruskan.', n_aset;
  END IF;

  -- (b) semuanya harus milik SKPD & golongan yang dimaksud.
  SELECT count(*) INTO n_luar
    FROM aset a JOIN stg_dup_pariwisata s ON s.nibar = a.nibar
   WHERE a.skpd_id <> 23 OR a.golongan <> '1.3.2';
  IF n_luar > 0 THEN
    RAISE EXCEPTION '% NIBAR bukan milik Dinas Pariwisata (skpd_id 23) / bukan golongan 1.3.2.', n_luar;
  END IF;

  -- (c) ⚠️ PALING PENTING: tak boleh ada yang SUDAH BERGERAK. Barang yang
  --     pernah direklas / dikoreksi / dipindah / dihapus / dikapitalisasi
  --     punya rantai peristiwa; menyembunyikannya diam-diam akan memutus
  --     rantai itu. Yang boleh cuma baris baseline & koreksi ganda dari
  --     migrasi ini sendiri (supaya bisa dijalankan ulang).
  SELECT count(DISTINCT t.aset_id) INTO n_gerak
    FROM transaksi_bmd t
    JOIN aset a ON a.id = t.aset_id
    JOIN stg_dup_pariwisata s ON s.nibar = a.nibar
   WHERE t.jenis NOT IN ('saldo_awal', 'saldo_awal_checkpoint', 'koreksi_pencatatan_ganda');
  IF n_gerak > 0 THEN
    RAISE EXCEPTION '% aset sudah punya peristiwa selain baseline (reklas/koreksi/pindah/hapus) — tinjau manual dulu.', n_gerak;
  END IF;

  -- (d) tanggal perolehan wajib ada — ia yang jadi tanggal backdate.
  SELECT count(*) INTO n_tglnull
    FROM aset a JOIN stg_dup_pariwisata s ON s.nibar = a.nibar
   WHERE a.tgl_perolehan IS NULL;
  IF n_tglnull > 0 THEN
    RAISE EXCEPTION '% aset tanpa tgl_perolehan — tak bisa di-backdate.', n_tglnull;
  END IF;

  -- (e) laporkan apa yang dibuang & apa yang tersisa (jangan diam-diam).
  SELECT count(*), round(sum(a.nilai_perolehan)) INTO n_aset, v_nilai
    FROM aset a JOIN stg_dup_pariwisata s ON s.nibar = a.nibar;
  SELECT count(*) INTO n_sisa
    FROM aset a
   WHERE a.skpd_id = 23 AND a.golongan = '1.3.2' AND a.status = 'aktif'
     AND NOT EXISTS (SELECT 1 FROM stg_dup_pariwisata s WHERE s.nibar = a.nibar);
  RAISE NOTICE 'Dibuang % barang senilai %; sisa 1.3.2 Dinas Pariwisata yang aktif: %', n_aset, v_nilai, n_sisa;
END $$;

-- ── 3. Cadangan baris snapshot SEBELUM dibuang ─────────────────────────────
-- Tanpa ini rollback tak lengkap: baris `aset_awal_2026` yang sudah di-DELETE
-- tak bisa disusun ulang dari mana pun (angkanya foto beku akhir 2025).
DROP TABLE IF EXISTS stg_dup_pariwisata_snapshot;
CREATE TABLE stg_dup_pariwisata_snapshot AS
SELECT w.* FROM aset_awal_2026 w
 WHERE w.nibar IN (SELECT nibar FROM stg_dup_pariwisata);

-- ── 4. Buang hasil engine untuk 248 aset itu ───────────────────────────────
-- `penyusutan_semester` TURUNAN (hasil engine), bukan ledger — boleh dihapus &
-- akan dihitung ulang. Kalau tidak dibuang, barisnya tertinggal basi: engine
-- berhenti di baris koreksi (berhenti=true) jadi ia tak pernah menimpanya lagi.
DELETE FROM penyusutan_semester p
 USING aset a
 WHERE p.aset_id = a.id
   AND a.nibar IN (SELECT nibar FROM stg_dup_pariwisata);

-- ── 5. Nonaktifkan duplikatnya lewat ledger (backdate) ─────────────────────
SELECT
  a.id,
  'koreksi_pencatatan_ganda',
  fn_periode_dari_tanggal(a.tgl_perolehan),
  a.tgl_perolehan,          -- backdate: barangnya dianggap tak pernah ada
  0,                        -- nilai 0: baris koreksi ganda tak pernah dijumlahkan
  NULL,
  jsonb_build_object(
    'sumber', 'Duplikat penyusunan awal Dinas Pariwisata — berkas import ter-paste 3x (migrasi 20260909_03)',
    'nilai_perolehan_duplikat', a.nilai_perolehan
  ),
  'Pencatatan ganda - salinan ke-2/ke-3 dari barang yang sama; salinan pertamanya dipertahankan'
FROM aset a
WHERE a.nibar IN (SELECT nibar FROM stg_dup_pariwisata)
  AND NOT EXISTS (
    SELECT 1 FROM transaksi_bmd t
     WHERE t.aset_id = a.id AND t.jenis = 'koreksi_pencatatan_ganda'
  );

-- ── 6. Status register ─────────────────────────────────────────────────────
UPDATE aset a
   SET status = 'dihapus'
 WHERE a.nibar IN (SELECT nibar FROM stg_dup_pariwisata)
   AND a.status <> 'dihapus';

-- ── 7. Buang baris snapshot Saldo Awal ─────────────────────────────────────
DELETE FROM aset_awal_2026
 WHERE nibar IN (SELECT nibar FROM stg_dup_pariwisata);

-- ============================================================================
-- PEMERIKSAAN SESUDAH DIJALANKAN (jalankan terpisah, di luar migrasi ini)
-- ============================================================================
-- 1. Keempatnya HARUS sesuai:
--      SELECT
--        (SELECT count(*) FROM aset a JOIN stg_dup_pariwisata s ON s.nibar=a.nibar
--          WHERE a.status='dihapus')                                   AS dihapus,   -- 248
--        (SELECT count(*) FROM transaksi_bmd t JOIN aset a ON a.id=t.aset_id
--          JOIN stg_dup_pariwisata s ON s.nibar=a.nibar
--          WHERE t.jenis='koreksi_pencatatan_ganda')                   AS koreksi,   -- 248
--        (SELECT count(*) FROM aset_awal_2026 w
--          JOIN stg_dup_pariwisata s ON s.nibar=w.nibar)               AS snapshot,  -- 0
--        (SELECT count(*) FROM aset a WHERE a.skpd_id=23
--          AND a.golongan='1.3.2' AND a.status='aktif')                AS sisa_aktif;-- 656
--    ⚠️ 656, BUKAN 124. Dinas Pariwisata punya DUA batch 1.3.2: import
--       2026-07-16 (532 barang, TIDAK tersentuh migrasi ini) + batch yang
--       ter-paste 3x 2026-09-04 (372 barang). 124 itu sisa BATCH-nya saja;
--       se-SKPD jadi 532 + 124 = 656. Diverifikasi ke produksi 2026-09-09.
--
-- 2. Baris koreksinya tak membawa uang (kalau bukan 0, ada yang salah):
--      SELECT coalesce(sum(nilai),0) FROM transaksi_bmd t
--        JOIN aset a ON a.id=t.aset_id JOIN stg_dup_pariwisata s ON s.nibar=a.nibar
--       WHERE t.jenis='koreksi_pencatatan_ganda';                      -- 0
--
-- 3. ⚠️ JALANKAN ENGINE 2026-S1 lalu 2026-S2 (menu Penyusutan → "Jalankan
--    Engine"). Sesudahnya, ke-248 aset itu HARUS tak punya baris engine lagi:
--      SELECT count(*) FROM penyusutan_semester p JOIN aset a ON a.id=p.aset_id
--        JOIN stg_dup_pariwisata s ON s.nibar=a.nibar;                 -- 0
--    dan alarm CLAUDE.md tetap bersih:
--      SELECT count(*) FROM penyusutan_semester WHERE akumulasi > nilai_perolehan + 0.5; -- 0
--
-- 4. Di layar: Daftar Barang & Penyusutan (SKPD Dinas Pariwisata, jenis 1.3.2,
--    Komptabel EKSTRAKOMPTABEL — bawaannya 'intra') harus tinggal 124 barang,
--    di periode 2026-S1 MAUPUN 2026-S2. Saldo Awal → Daftar Barang Awal juga.
--
-- 5. Uji Konsistensi (Pelaporan → Uji Konsistensi) 2026-S1 & 2026-S2:
--    Rekonsiliasi BMD vs Laporan BMD tetap selisih 0,00 di semua golongan.
--
-- ============================================================================
-- ROLLBACK (kalau ternyata daftar NIBAR-nya keliru)
-- ============================================================================
--   -- (i) hidupkan lagi barangnya — pola batal_penghapusan, ledger tetap utuh:
--   INSERT INTO transaksi_bmd (aset_id, jenis, periode, tanggal, nilai, header_id, payload, keterangan)
--   SELECT t.aset_id, 'batal_koreksi_pencatatan_ganda', t.periode, t.tanggal, 0, NULL,
--          jsonb_build_object('target_trx_id', t.id, 'sumber', 'Rollback migrasi 20260909_03'),
--          'Batal pencatatan ganda - daftar duplikat ternyata keliru'
--     FROM transaksi_bmd t JOIN aset a ON a.id = t.aset_id
--    WHERE t.jenis = 'koreksi_pencatatan_ganda'
--      AND a.nibar IN (SELECT nibar FROM stg_dup_pariwisata)
--      AND (t.payload->>'sumber') LIKE '%20260909_03%';
--
--   UPDATE aset SET status='aktif'
--    WHERE nibar IN (SELECT nibar FROM stg_dup_pariwisata) AND status='dihapus';
--
--   -- (ii) pulihkan baris snapshotnya dari cadangan langkah 3:
--   INSERT INTO aset_awal_2026 SELECT * FROM stg_dup_pariwisata_snapshot
--     ON CONFLICT (nibar) DO NOTHING;
--
--   -- (iii) JALANKAN ENGINE 2026-S1 & 2026-S2 lagi.
-- ============================================================================
